1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string };
10	
11	type Scenario = {
12	  steps: { items: Item[] }[];
13	};
14	
15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const BASE_PREMIUMS: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	};
23	
24	const basePremiumOf = (items: Item[]): number =>
25	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
26	
27	const quotePremium = (items: Item[]): number => {
28	  const base = basePremiumOf(items);
29	
30	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
31	};
32	
33	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
34	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
35	});
